#include "EventNotificationMapping.h"
EventNotificationMapping::EventNotificationMapping():eventType_(EventType::NONE),minimumSeverity_(EventSeverity::COUNT),channelId_(0U),priority_(NotificationPriority::COUNT),ttlMs_(0U),target_(nullptr),targetLength_(0U),enabled_(false),valid_(false){}
EventNotificationMapping EventNotificationMapping::create(EventType type,EventSeverity severity,NotificationChannelId channel,NotificationPriority priority,NotificationDuration ttl,const char* target,size_t length,bool enabled){EventNotificationMapping r;if(type==EventType::NONE||!isValidEventType(type)||!isValidEventSeverity(severity)||channel==0U||!isValidNotificationPriority(priority)||ttl==0U||target==nullptr||length==0U||length>NOTIFICATION_RUNTIME_MAX_TARGET_LENGTH)return r;r.eventType_=type;r.minimumSeverity_=severity;r.channelId_=channel;r.priority_=priority;r.ttlMs_=ttl;r.target_=target;r.targetLength_=length;r.enabled_=enabled;r.valid_=true;return r;}
bool EventNotificationMapping::isValid()const{return valid_&&eventType_!=EventType::NONE&&isValidEventType(eventType_)&&isValidEventSeverity(minimumSeverity_)&&channelId_!=0U&&isValidNotificationPriority(priority_)&&ttlMs_!=0U&&target_!=nullptr&&targetLength_>0U&&targetLength_<=NOTIFICATION_RUNTIME_MAX_TARGET_LENGTH;}
EventType EventNotificationMapping::eventType()const{return eventType_;}EventSeverity EventNotificationMapping::minimumSeverity()const{return minimumSeverity_;}NotificationChannelId EventNotificationMapping::channelId()const{return channelId_;}NotificationPriority EventNotificationMapping::priority()const{return priority_;}NotificationDuration EventNotificationMapping::ttlMs()const{return ttlMs_;}const char* EventNotificationMapping::target()const{return target_;}size_t EventNotificationMapping::targetLength()const{return targetLength_;}bool EventNotificationMapping::enabled()const{return enabled_;}
